### 1. Konfigurationsklasse für die Allowlist

`RemoteFetchProperties` bindet die erlaubten Ziel-Hosts und Timeouts aus `application.yml`. Die Allowlist ist die zentrale Verteidigungslinie gegen SSRF.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RemoteFetchProperties.java
package com.example.securefetch.config;

import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Positive;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;
import org.springframework.validation.annotation.Validated;

import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Zentrale, extern konfigurierbare Sicherheitsparameter für den
 * ausgehenden HTTPS-Abruf. Die Allowlist verhindert Server-Side
 * Request Forgery (SSRF, CWE-918 / OWASP A10:2021).
 */
@Component
@Validated
@ConfigurationProperties(prefix = "app.remote-fetch")
public class RemoteFetchProperties {

    @NotEmpty
    private Set<String> allowedHosts = new LinkedHashSet<>();

    @Positive
    private long connectTimeoutMillis = 3000L;

    @Positive
    private long responseTimeoutMillis = 5000L;

    @Positive
    private long maxResponseBytes = 1_048_576L; // 1 MiB Obergrenze

    public Set<String> getAllowedHosts() {
        return allowedHosts;
    }

    public void setAllowedHosts(Set<String> allowedHosts) {
        this.allowedHosts = allowedHosts;
    }

    public long getConnectTimeoutMillis() {
        return connectTimeoutMillis;
    }

    public void setConnectTimeoutMillis(long connectTimeoutMillis) {
        this.connectTimeoutMillis = connectTimeoutMillis;
    }

    public long getResponseTimeoutMillis() {
        return responseTimeoutMillis;
    }

    public void setResponseTimeoutMillis(long responseTimeoutMillis) {
        this.responseTimeoutMillis = responseTimeoutMillis;
    }

    public long getMaxResponseBytes() {
        return maxResponseBytes;
    }

    public void setMaxResponseBytes(long maxResponseBytes) {
        this.maxResponseBytes = maxResponseBytes;
    }
}
