### 4. DNS-Pinning-Resolver gegen DNS-Rebinding

Der `PinnedDnsResolver` wird vom Connection-Pool des HTTP-Clients **einmalig pro Verbindung** aufgerufen. Dadurch wird die aufgelöste IP-Adresse für die Dauer der Verbindung fixiert ("gepinnt") – ein Angreifer kann die DNS-Antwort nach der Prüfung nicht mehr austauschen (klassisches TOCTOU-Muster bei DNS-Rebinding, CWE-350/CWE-180). Zusätzlich werden private/interne Adressbereiche als Defense-in-Depth ausgeschlossen, selbst wenn ein Allowlist-Eintrag später auf eine interne Adresse zeigen sollte.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// PinnedDnsResolver.java
package com.example.securefetch.net;

import org.apache.hc.client5.http.DnsResolver;
import org.springframework.stereotype.Component;

import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Arrays;

/**
 * Löst einen Hostnamen genau einmal auf und filtert dabei
 * private/interne Adressbereiche heraus. Die zurückgegebene
 * Adresse wird vom HttpClient für die gesamte Verbindungsdauer
 * verwendet ("DNS Pinning"), was klassisches DNS-Rebinding
 * (CWE-350 / CWE-180) verhindert.
 */
@Component
public class PinnedDnsResolver implements DnsResolver {

    @Override
    public InetAddress[] resolve(String host) throws UnknownHostException {
        InetAddress[] resolved = InetAddress.getAllByName(host);

        InetAddress[] filtered = Arrays.stream(resolved)
                .filter(this::isPubliclyRoutable)
                .toArray(InetAddress[]::new);

        if (filtered.length == 0) {
            throw new UnknownHostException(
                    "No publicly routable address could be resolved for host: " + host);
        }

        return filtered;
    }

    private boolean isPubliclyRoutable(InetAddress address) {
        return !address.isLoopbackAddress()
                && !address.isLinkLocalAddress()
                && !address.isSiteLocalAddress()
                && !address.isMulticastAddress()
                && !address.isAnyLocalAddress();
    }
}
