### 5. Sicherer HTTP-Client (TLS 1.2+, starke Ciphersuiten, strikte Hostname-Prüfung)

Diese Konfiguration erzwingt TLS 1.2/1.3, eine feste Liste starker GCM-Cipher, die **strikte** `DefaultHostnameVerifier`-Implementierung (kein "Toleranz"-Modus) und nutzt den JDK-Standard-Truststore (`sslContext.init(null, null, null)` – keine eigene, potenziell zu lasche `TrustManager`-Implementierung). Zusätzlich wird `disableRedirectHandling()` gesetzt, um SSRF via Redirect-Kette (z. B. `https://api.trusted.example` → `http://169.254.169.254/`) zu verhindern.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureHttpClientConfig.java
package com.example.securefetch.config;

import com.example.securefetch.net.PinnedDnsResolver;
import org.apache.hc.client5.http.config.ConnectionConfig;
import org.apache.hc.client5.http.config.RequestConfig;
import org.apache.hc.client5.http.impl.classic.CloseableHttpClient;
import org.apache.hc.client5.http.impl.classic.HttpClients;
import org.apache.hc.client5.http.impl.io.PoolingHttpClientConnectionManager;
import org.apache.hc.client5.http.impl.io.PoolingHttpClientConnectionManagerBuilder;
import org.apache.hc.client5.http.ssl.DefaultHostnameVerifier;
import org.apache.hc.client5.http.ssl.SSLConnectionSocketFactory;
import org.apache.hc.core5.util.Timeout;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import javax.net.ssl.SSLContext;
import java.security.NoSuchAlgorithmException;
import java.security.KeyManagementException;

/**
 * Baut einen HttpClient mit erzwungenem TLS 1.2/1.3, starken
 * Ciphersuiten und strikter Zertifikats-/Hostname-Validierung.
 * Adressiert CWE-295 (Improper Certificate Validation) und
 * CWE-326 (Inadequate Encryption Strength) sowie die TLS-Vorgaben
 * (nur GCM-Ciphers, keine SSLv2/v3/TLSv1.0/1.1, kein
 * Kompressions-Overhead, s. TLS Cheat Sheet).
 */
@Configuration
public class SecureHttpClientConfig {

    private static final String[] ENABLED_PROTOCOLS = {"TLSv1.3", "TLSv1.2"};

    private static final String[] STRONG_CIPHER_SUITES = {
            "TLS_AES_128_GCM_SHA256",
            "TLS_AES_256_GCM_SHA384",
            "TLS_CHACHA20_POLY1305_SHA256",
            "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
            "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
            "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256",
            "TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384"
    };

    @Bean
    public CloseableHttpClient secureHttpClient(RemoteFetchProperties properties,
                                                 PinnedDnsResolver dnsResolver)
            throws NoSuchAlgorithmException, KeyManagementException {

        // Explizit TLSv1.2 als Mindeststandard anfordern (kein generisches "TLS",
        // das je nach JDK-Provider auch veraltete Protokolle wie TLSv1.0/1.1
        // oder SSL erlauben könnte).
        SSLContext sslContext = SSLContext.getInstance("TLSv1.2");
        sslContext.init(null, null, null);

        SSLConnectionSocketFactory sslSocketFactory = new SSLConnectionSocketFactory(
                sslContext,
                ENABLED_PROTOCOLS,
                STRONG_CIPHER_SUITES,
                new DefaultHostnameVerifier() // strikte RFC-konforme Prüfung, keine Toleranz
        );

        PoolingHttpClientConnectionManager connectionManager =
                PoolingHttpClientConnectionManagerBuilder.create()
                        .setDnsResolver(dnsResolver)
                        .setSSLSocketFactory(sslSocketFactory)
                        .setMaxConnTotal(50)
                        .setMaxConnPerRoute(10)
                        .build();

        connectionManager.setDefaultConnectionConfig(ConnectionConfig.custom()
                .setConnectTimeout(Timeout.ofMilliseconds(properties.getConnectTimeoutMillis()))
                .setSocketTimeout(Timeout.ofMilliseconds(properties.getResponseTimeoutMillis()))
                .build());

        RequestConfig requestConfig = RequestConfig.custom()
                .setResponseTimeout(Timeout.ofMilliseconds(properties.getResponseTimeoutMillis()))
                .setConnectionRequestTimeout(Timeout.ofMilliseconds(properties.getConnectTimeoutMillis()))
                .build();

        return HttpClients.custom()
                .setConnectionManager(connectionManager)
                .setDefaultRequestConfig(requestConfig)
                // Verhindert SSRF via Redirect auf nicht erlaubte Ziele
                .disableRedirectHandling()
                .disableAutomaticRetries()
                .build();
    }
}
