### 7. Service-Schicht: Ausführung des sicheren Abrufs

`RemoteFetchService` verbindet Validierung, sicheren Client und Antwortbegrenzung. Die Antwortgröße wird aktiv begrenzt, um unkontrollierten Ressourcenverbrauch durch überdimensionierte Upstream-Antworten zu verhindern (CWE-770).

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RemoteFetchService.java
package com.example.securefetch.service;

import com.example.securefetch.config.RemoteFetchProperties;
import com.example.securefetch.dto.RemoteDataResponse;
import com.example.securefetch.exception.RemoteFetchException;
import com.example.securefetch.validation.HostValidator;
import org.apache.hc.client5.http.classic.methods.HttpGet;
import org.apache.hc.core5.http.ClassicHttpResponse;
import org.apache.hc.core5.http.HttpEntity;
import org.apache.hc.core5.http.io.HttpClientResponseHandler;
import org.apache.hc.client5.http.impl.classic.CloseableHttpClient;
import org.springframework.stereotype.Service;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.util.Set;

/**
 * Führt den validierten, TLS-gesicherten Abruf gegen einen
 * Allowlist-geprüften Host durch und liefert eine kuratierte,
 * größenbegrenzte Antwort zurück.
 */
@Service
public class RemoteFetchService {

    private static final Set<String> ALLOWED_CONTENT_TYPES = Set.of(
            "text/plain", "text/html", "application/json", "application/xml");

    private final CloseableHttpClient httpClient;
    private final HostValidator hostValidator;
    private final RemoteFetchProperties properties;

    public RemoteFetchService(CloseableHttpClient httpClient,
                               HostValidator hostValidator,
                               RemoteFetchProperties properties) {
        this.httpClient = httpClient;
        this.hostValidator = hostValidator;
        this.properties = properties;
    }

    public RemoteDataResponse fetchSecurely(String rawHost) {
        String validatedHost = hostValidator.validateAndNormalize(rawHost);
        URI targetUri = buildHttpsUri(validatedHost);

        HttpGet request = new HttpGet(targetUri);

        HttpClientResponseHandler<RemoteDataResponse> responseHandler = response ->
                mapResponse(response, properties.getMaxResponseBytes());

        try {
            return httpClient.execute(request, responseHandler);
        } catch (IOException e) {
            throw new RemoteFetchException("Failed to retrieve data from the target host.", e);
        }
    }

    private URI buildHttpsUri(String host) {
        try {
            return new URI("https", host, "/", null);
        } catch (URISyntaxException e) {
            throw new RemoteFetchException("Unable to construct a valid HTTPS URI.", e);
        }
    }

    private RemoteDataResponse mapResponse(ClassicHttpResponse response, long maxBytes)
            throws IOException {

        int statusCode = response.getCode();
        HttpEntity entity = response.getEntity();

        String rawContentType = entity != null ? entity.getContentType() : null;
        String contentType = sanitizeContentType(rawContentType);
        String body = readBounded(entity, maxBytes);

        return new RemoteDataResponse(statusCode, contentType, body);
    }

    private String sanitizeContentType(String rawContentType) {
        if (rawContentType == null) {
            return "text/plain";
        }
        String base = rawContentType.split(";")[0].trim().toLowerCase();
        return ALLOWED_CONTENT_TYPES.contains(base) ? base : "text/plain";
    }

    private String readBounded(HttpEntity entity, long maxBytes) throws IOException {
        if (entity == null) {
            return "";
        }
        try (InputStream in = entity.getContent()) {
            ByteArrayOutputStream buffer = new ByteArrayOutputStream();
            byte[] chunk = new byte[8192];
            long total = 0;
            int read;
            while ((read = in.read(chunk)) != -1) {
                total += read;
                if (total > maxBytes) {
                    throw new RemoteFetchException("Upstream response exceeded the maximum allowed size.");
                }
                buffer.write(chunk, 0, read);
            }
            return buffer.toString(StandardCharsets.UTF_8);
        }
    }
}
