### 8. REST-Controller

Der Controller ist bewusst schmal gehalten und setzt zusätzlich Cache-Steuerungs-Header, da potenziell sensible Upstream-Daten nicht von Browsern oder Proxies zwischengespeichert werden sollen (gemäß TLS-Cheat-Sheet-Empfehlung zur Caching-Vermeidung).

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RemoteFetchController.java
package com.example.securefetch.controller;

import com.example.securefetch.dto.RemoteDataResponse;
import com.example.securefetch.service.RemoteFetchService;
import org.springframework.http.CacheControl;
import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.concurrent.TimeUnit;

/**
 * Endpoint zum sicheren Abruf von Daten eines Allowlist-geprüften
 * HTTPS-Ziels. Antworten werden explizit als nicht-cachebar markiert.
 */
@RestController
public class RemoteFetchController {

    private final RemoteFetchService remoteFetchService;

    public RemoteFetchController(RemoteFetchService remoteFetchService) {
        this.remoteFetchService = remoteFetchService;
    }

    @GetMapping("/api/remote-data")
    public ResponseEntity<RemoteDataResponse> fetch(@RequestParam("host") String host) {
        RemoteDataResponse data = remoteFetchService.fetchSecurely(host);

        return ResponseEntity.ok()
                .cacheControl(CacheControl.noStore().mustRevalidate())
                .header(HttpHeaders.PRAGMA, "no-cache")
                .header(HttpHeaders.EXPIRES, "0")
                .body(data);
    }
}
