### 9. Zentrale Fehlerbehandlung

Fehlermeldungen an den Client bleiben generisch; Details landen nur im Server-Log (hier exemplarisch über SLF4J), um Informationspreisgabe (CWE-209) zu vermeiden.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.securefetch.controller;

import com.example.securefetch.dto.ErrorResponse;
import com.example.securefetch.exception.InvalidHostException;
import com.example.securefetch.exception.RemoteFetchException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Übersetzt fachliche Exceptions in generische, informationsarme
 * HTTP-Fehlerantworten und vermeidet das Leaken interner Details.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(InvalidHostException.class)
    public ResponseEntity<ErrorResponse> handleInvalidHost(InvalidHostException ex) {
        log.warn("Invalid host rejected: {}", ex.getMessage());
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorResponse("INVALID_HOST", "The provided host is not permitted."));
    }

    @ExceptionHandler(RemoteFetchException.class)
    public ResponseEntity<ErrorResponse> handleFetchFailure(RemoteFetchException ex) {
        log.warn("Remote fetch failed", ex);
        return ResponseEntity.status(HttpStatus.BAD_GATEWAY)
                .body(new ErrorResponse("UPSTREAM_ERROR", "Unable to retrieve data from the target host."));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleUnexpected(Exception ex) {
        log.error("Unexpected error while processing request", ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(new ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred."));
    }
}
