package com.example.notes.validation;

import com.example.notes.exception.InvalidUserIdException;

import java.util.regex.Pattern;

/**
 * Zentrale, strikte Allowlist-Validierung für userId-Werte.
 *
 * Nur alphanumerische Zeichen sowie Unterstrich und Bindestrich sind
 * erlaubt, Länge zwischen 3 und 64 Zeichen. Dadurch werden Metazeichen,
 * die für SQL-Injection (CWE-89), Pfad-Traversal (CWE-22) oder
 * KeyStore-Alias-Manipulation missbraucht werden könnten, zuverlässig
 * ausgeschlossen - unabhängig davon, wo die userId später verwendet wird.
 */
public final class UserIdValidator {

    private static final Pattern ALLOWED_USER_ID = Pattern.compile("^[a-zA-Z0-9_-]{3,64}$");

    private UserIdValidator() {
        // Utility-Klasse, keine Instanziierung
    }

    public static String validate(String userId) {
        if (userId == null || !ALLOWED_USER_ID.matcher(userId).matches()) {
            throw new InvalidUserIdException("userId has an invalid format");
        }
        return userId;
    }
}
