package com.example.notes.crypto;

import javax.crypto.SecretKey;

/**
 * Abstraktion für die Beschaffung eines nutzerspezifischen symmetrischen
 * Schlüssels. Durch dieses Interface kann die konkrete Secret-Quelle
 * (lokaler JKS-KeyStore, HashiCorp Vault, AWS/Azure Secrets Manager, ...)
 * ausgetauscht werden, ohne den Aufrufercode zu ändern
 * (Dependency Inversion Principle).
 */
public interface UserKeyProvider {

    /**
     * Liefert den symmetrischen Schlüssel für die angegebene, bereits
     * validierte userId.
     *
     * @param validatedUserId eine userId, die bereits erfolgreich
     *                        UserIdValidator.validate() durchlaufen hat
     * @return der zugehörige SecretKey
     */
    SecretKey getKeyForUser(String validatedUserId);
}
