"}, {"type": "CODE_BLOCK", "language": "java", "content": "// KeyStoreUserKeyProvider.java
package com.example.notes.crypto;

import com.example.notes.config.KeyStoreProperties;
import com.example.notes.exception.EncryptionOperationException;
import com.example.notes.exception.KeyNotFoundException;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.KeyStore;
import java.security.KeyStoreException;
import java.security.NoSuchAlgorithmException;
import java.security.UnrecoverableKeyException;
import java.security.cert.CertificateException;

/**
 * Implementierung von UserKeyProvider auf Basis eines Java KeyStore (JKS/PKCS12).
 *
 * Der KeyStore wird bei jedem Zugriff frisch geladen (kein dauerhaftes Caching
 * des Passworts im Speicher über die Methode hinaus), das Alias-Lookup nutzt
 * ausschliesslich die bereits validierte userId, sodass keine Konkatenation
 * mit Nutzereingaben in Datei- oder Systempfade erfolgt.
 *
 * Schlüssel müssen vorab durch einen separaten, administrativen Prozess
 * (z.B. "keytool -genseckey") im KeyStore angelegt werden. Es findet
 * KEINE automatische Schlüsselerzeugung zur Laufzeit statt.
 */
@Component
public class KeyStoreUserKeyProvider implements UserKeyProvider {

    private final KeyStoreProperties properties;

    public KeyStoreUserKeyProvider(KeyStoreProperties properties) {
        this.properties = properties;
    }

    @Override
    public SecretKey getKeyForUser(String validatedUserId) {
        char[] storePassword = properties.getPassword().toCharArray();
        try (FileInputStream keyStoreStream = new FileInputStream(properties.getPath())) {
            KeyStore keyStore = KeyStore.getInstance(properties.getType());
            keyStore.load(keyStoreStream, storePassword);

            if (!keyStore.containsAlias(validatedUserId)) {
                throw new KeyNotFoundException("No key configured for the given userId");
            }

            SecretKey key = (SecretKey) keyStore.getKey(validatedUserId, storePassword);
            if (key == null) {
                throw new KeyNotFoundException("No key configured for the given userId");
            }
            return key;

        } catch (IOException | NoSuchAlgorithmException | CertificateException
                 | KeyStoreException | UnrecoverableKeyException e) {
            // Keine Detailinformationen (Pfad, Passwort, Stacktrace) an den Aufrufer weitergeben.
            throw new EncryptionOperationException("Unable to access key material", e);
        } finally {
            java.util.Arrays.fill(storePassword, '\0');
        }
    }
}
