"}, {"type": "CODE_BLOCK", "language": "java", "content": "// AesGcmNoteEncryptionService.java
package com.example.notes.crypto;

import com.example.notes.exception.EncryptionOperationException;
import org.springframework.stereotype.Service;

import javax.crypto.Cipher;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.SecureRandom;

/**
 * Führt die eigentliche symmetrische Verschlüsselung mittels AES-256-GCM aus.
 *
 * WICHTIG: Für jeden Aufruf wird ein neuer, kryptografisch sicherer Zufalls-Nonce
 * erzeugt (SecureRandom). Dadurch ist die Verschlüsselung NICHT deterministisch -
 * zwei identische Klartexte erzeugen unterschiedliche Chiffretexte. Dies ist eine
 * bewusste Sicherheitsentscheidung (Vermeidung von CWE-327 durch semantisch
 * sichere Verschlüsselung) und weicht von der ursprünglichen Anforderung
 * "deterministischer" Ergebnisse ab.
 */
@Service
public class AesGcmNoteEncryptionService {

    private static final String CIPHER_ALGORITHM = "AES/GCM/NoPadding";
    private static final int TAG_LENGTH_BITS = 128;
    private static final int NONCE_LENGTH_BYTES = 12;

    private final UserKeyProvider userKeyProvider;
    private final SecureRandom secureRandom = new SecureRandom();

    public AesGcmNoteEncryptionService(UserKeyProvider userKeyProvider) {
        this.userKeyProvider = userKeyProvider;
    }

    /**
     * Verschlüsselt den übergebenen Klartext mit dem Schlüssel der angegebenen,
     * bereits validierten userId.
     */
    public NoteEncryptionResult encrypt(String plainText, String validatedUserId) {
        SecretKey secretKey = userKeyProvider.getKeyForUser(validatedUserId);

        byte[] nonce = new byte[NONCE_LENGTH_BYTES];
        secureRandom.nextBytes(nonce);

        try {
            Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
            GCMParameterSpec gcmSpec = new GCMParameterSpec(TAG_LENGTH_BITS, nonce);
            cipher.init(Cipher.ENCRYPT_MODE, secretKey, gcmSpec);

            byte[] cipherText = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));
            return new NoteEncryptionResult(cipherText, nonce);

        } catch (GeneralSecurityException e) {
            throw new EncryptionOperationException("Encryption failed", e);
        }
    }
}
