package com.example.notes.controller;

import com.example.notes.crypto.AesGcmNoteEncryptionService;
import com.example.notes.crypto.NoteEncryptionResult;
import com.example.notes.dto.EncryptNoteRequest;
import com.example.notes.dto.EncryptedNoteResponse;
import com.example.notes.validation.UserIdValidator;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Base64;

/**
 * REST-Endpunkt zum Verschlüsseln von Notiz-Texten.
 *
 * Sicherheitsmassnahmen in diesem Controller:
 * - Bean Validation auf dem Request-Body (Länge, Pflichtfeld) verhindert
 *   übergrosse oder leere Payloads.
 * - Strikte Allowlist-Validierung der userId verhindert Injection-Angriffe
 *   (CWE-89) sowie Missbrauch als Pfad- oder Alias-Manipulation (CWE-22).
 * - Es werden weder Klartext noch Schlüsselmaterial geloggt.
 */
@RestController
public class NotesController {

    private final AesGcmNoteEncryptionService encryptionService;

    public NotesController(AesGcmNoteEncryptionService encryptionService) {
        this.encryptionService = encryptionService;
    }

    @PostMapping("/api/notes/encrypt")
    public ResponseEntity<EncryptedNoteResponse> encryptNote(
            @Valid @RequestBody EncryptNoteRequest request,
            @RequestParam("userId") String userId) {

        String validatedUserId = UserIdValidator.validate(userId);

        NoteEncryptionResult result = encryptionService.encrypt(request.getText(), validatedUserId);

        String cipherTextBase64 = Base64.getEncoder().encodeToString(result.getCipherText());
        String nonceBase64 = Base64.getEncoder().encodeToString(result.getNonce());

        EncryptedNoteResponse response =
                new EncryptedNoteResponse(validatedUserId, cipherTextBase64, nonceBase64);

        return ResponseEntity.ok(response);
    }
}
