"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ApiExceptionHandler.java
package com.example.notes.controller;

import com.example.notes.exception.EncryptionOperationException;
import com.example.notes.exception.InvalidUserIdException;
import com.example.notes.exception.KeyNotFoundException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

/**
 * Zentrale Fehlerbehandlung für die Notes-API.
 *
 * Gibt bewusst generische, technische Details vermeidende Fehlermeldungen
 * zurück, um Information Disclosure (CWE-209) zu verhindern. Interne
 * Ursachen (z.B. Stacktrace, Pfade, Schlüsselmaterial) werden ausschliesslich
 * serverseitig protokolliert, niemals an den Client übermittelt.
 */
@RestControllerAdvice
public class ApiExceptionHandler {

    private static final Logger LOGGER = LoggerFactory.getLogger(ApiExceptionHandler.class);

    @ExceptionHandler(InvalidUserIdException.class)
    public ResponseEntity<Map<String, String>> handleInvalidUserId(InvalidUserIdException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(Map.of("error", "Invalid userId format"));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, String>> handleValidationError(MethodArgumentNotValidException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(Map.of("error", "Invalid request payload"));
    }

    @ExceptionHandler(KeyNotFoundException.class)
    public ResponseEntity<Map<String, String>> handleKeyNotFound(KeyNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(Map.of("error", "No key configured for this user"));
    }

    @ExceptionHandler(EncryptionOperationException.class)
    public ResponseEntity<Map<String, String>> handleEncryptionError(EncryptionOperationException ex) {
        // Vollständige Ursache nur serverseitig loggen, strukturiert und ohne
        // Nutzereingaben im Nachrichtentext (Vermeidung von Log Injection, CWE-93).
        LOGGER.error("Encryption operation failed", ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Map.of("error", "Internal server error"));
    }
}
