package com.example.partner.order;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

import java.math.BigDecimal;

/**
 * DTO für den Callback-Request-Body.
 *
 * Alle Felder werden strikt validiert (Allow-list-Validierung gemäß
 * OWASP Input Validation Cheat Sheet), bevor sie überhaupt die Service-Schicht
 * erreichen. Dadurch werden ungültige oder potenziell schädliche Eingaben
 * (z. B. Steuerzeichen, überlange Strings, negative Beträge) frühzeitig
 * mit HTTP 400 abgelehnt.
 */
public class OrderCallbackRequest {

    @NotNull(message = "orderId must not be null")
    @Pattern(
            regexp = "^[A-Za-z0-9_-]{1,64}$",
            message = "orderId must be alphanumeric (with '-' or '_') and at most 64 characters long"
    )
    private String orderId;

    @NotNull(message = "status must not be null")
    private OrderStatus status;

    @NotNull(message = "amount must not be null")
    @DecimalMin(value = "0.00", inclusive = true, message = "amount must not be negative")
    @Digits(integer = 12, fraction = 2, message = "amount has an invalid numeric format")
    private BigDecimal amount;

    public OrderCallbackRequest() {
    }

    public String getOrderId() {
        return orderId;
    }

    public void setOrderId(String orderId) {
        this.orderId = orderId;
    }

    public OrderStatus getStatus() {
        return status;
    }

    public void setStatus(OrderStatus status) {
        this.status = status;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }
}
