package com.example.partner.order;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.Optional;

/**
 * Repository mit einer explizit parametrisierten JPQL-Query.
 *
 * Der Wert von "orderId" wird niemals per String-Konkatenation in die
 * Query eingefügt, sondern ausschließlich über den benannten Parameter
 * ":orderId" gebunden. Spring Data übersetzt dies intern in ein
 * PreparedStatement mit gebundener Variable – die Datenbank unterscheidet
 * somit strikt zwischen SQL-Code und Nutzdaten (Schutz vor CWE-89).
 */
public interface OrderRepository extends JpaRepository<Order, Long> {

    @Query("SELECT o FROM Order o WHERE o.orderId = :orderId")
    Optional<Order> findByOrderId(@Param("orderId") String orderId);
}
