package com.example.partner.order;

import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Implementiert die Upsert-Logik: existiert die orderId bereits, wird sie
 * aktualisiert, andernfalls neu angelegt. Die eindeutige Datenbank-Constraint
 * auf "order_id" fängt Race Conditions bei parallelen Callbacks ab.
 */
@Service
public class OrderServiceImpl implements OrderService {

    private final OrderRepository orderRepository;

    public OrderServiceImpl(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Override
    @Transactional
    public void upsertOrder(OrderCallbackRequest request) {
        orderRepository.findByOrderId(request.getOrderId())
                .ifPresentOrElse(
                        existing -> updateExisting(existing, request),
                        () -> createNew(request)
                );
    }

    private void updateExisting(Order existing, OrderCallbackRequest request) {
        existing.setStatus(request.getStatus());
        existing.setAmount(request.getAmount());
        orderRepository.save(existing);
    }

    private void createNew(OrderCallbackRequest request) {
        Order newOrder = new Order(request.getOrderId(), request.getStatus(), request.getAmount());
        try {
            orderRepository.save(newOrder);
        } catch (DataIntegrityViolationException concurrentInsert) {
            // Ein paralleler Request hat dieselbe orderId inzwischen bereits angelegt.
            // Um Callbacks idempotent zu verarbeiten, wird auf ein Update zurückgefallen.
            orderRepository.findByOrderId(request.getOrderId())
                    .ifPresent(existing -> updateExisting(existing, request));
        }
    }
}
