package com.example.partner.security;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType;
import org.springframework.security.authentication.AuthenticationServiceException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.util.AntPathMatcher;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.web.util.ContentCachingRequestWrapper;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Collections;
import java.util.List;

/**
 * Authentifiziert eingehende Partner-Callbacks über eine HMAC-SHA256-Signatur
 * (Header "X-Partner-Signature") anstelle eines klassischen CSRF-Tokens.
 *
 * Begründung: Ein CSRF-Token setzt eine authentifizierte Browser-Session mit
 * Cookies voraus. Bei einem Server-zu-Server-Webhook gibt es keine solche
 * Session – die Authentizität des Aufrufers muss stattdessen kryptografisch
 * über ein gemeinsames Geheimnis nachgewiesen werden. Der Vergleich der
 * Signaturen erfolgt zeitkonstant (MessageDigest.isEqual), um Timing-Angriffe
 * zu verhindern.
 */
public class PartnerSignatureFilter extends OncePerRequestFilter {

    private static final Logger log = LoggerFactory.getLogger(PartnerSignatureFilter.class);
    private static final String SIGNATURE_HEADER = "X-Partner-Signature";
    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final AntPathMatcher PATH_MATCHER = new AntPathMatcher();

    private final String sharedSecret;
    private final List<String> protectedPaths;

    public PartnerSignatureFilter(String sharedSecret, List<String> protectedPaths) {
        this.sharedSecret = sharedSecret;
        this.protectedPaths = protectedPaths;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        String path = request.getRequestURI();
        return protectedPaths.stream().noneMatch(pattern -> PATH_MATCHER.match(pattern, path));
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                     HttpServletResponse response,
                                     FilterChain filterChain) throws ServletException, IOException {

        ContentCachingRequestWrapper cachingRequest = new ContentCachingRequestWrapper(request);
        // Body einmal vollständig lesen, damit ContentCachingRequestWrapper ihn
        // für den nachfolgenden Controller zwischenspeichern kann.
        byte[] body = cachingRequest.getInputStream().readAllBytes();

        String providedSignature = request.getHeader(SIGNATURE_HEADER);

        try {
            validateSignature(providedSignature, body);
        } catch (InvalidSignatureException ex) {
            log.warn("Rejected partner callback: {}", sanitizeForLog(ex.getMessage()));
            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
            response.getWriter().write(
                    "{\"error\":\"Unauthorized\",\"message\":\"Partner authentication failed.\"}");
            return;
        } catch (Exception ex) {
            throw new AuthenticationServiceException("Unable to verify partner signature", ex);
        }

        UsernamePasswordAuthenticationToken authentication = new UsernamePasswordAuthenticationToken(
                "partner", null,
                Collections.singletonList(new SimpleGrantedAuthority("ROLE_PARTNER")));
        SecurityContextHolder.getContext().setAuthentication(authentication);

        filterChain.doFilter(cachingRequest, response);
    }

    private void validateSignature(String providedSignature, byte[] body) throws Exception {
        if (providedSignature == null || providedSignature.isBlank()) {
            throw new InvalidSignatureException("Missing partner signature header");
        }
        String expectedSignature = computeHmac(body, sharedSecret);
        if (!constantTimeEquals(expectedSignature, providedSignature)) {
            throw new InvalidSignatureException("Signature mismatch");
        }
    }

    private String computeHmac(byte[] payload, String secret) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALGORITHM);
        mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM));
        byte[] rawHmac = mac.doFinal(payload);
        StringBuilder hex = new StringBuilder();
        for (byte b : rawHmac) {
            hex.append(String.format("%02x", b));
        }
        return hex.toString();
    }

    private boolean constantTimeEquals(String a, String b) {
        return MessageDigest.isEqual(
                a.getBytes(StandardCharsets.UTF_8),
                b.getBytes(StandardCharsets.UTF_8));
    }

    private String sanitizeForLog(String input) {
        if (input == null) {
            return "";
        }
        // Verhindert Log-Injection (CWE-117) durch Entfernen von Zeilenumbrüchen.
        return input.replaceAll("[\r\n]", "_");
    }
}
