"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.partner.security;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.security.web.util.matcher.AntPathRequestMatcher;

import java.util.List;

/**
 * Zentrale Security-Konfiguration.
 *
 * CSRF wird ausschließlich für den zustandslosen Partner-Callback-Pfad
 * deaktiviert, weil dort keine Browser-Session/Cookies verwendet werden
 * (klassisches CSRF-Modell greift nicht). Stattdessen erzwingt der
 * PartnerSignatureFilter eine HMAC-Signaturprüfung. Für alle übrigen,
 * potenziell browserbasierten Endpunkte bleibt der Standard-CSRF-Schutz
 * von Spring Security aktiv.
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private static final String PARTNER_CALLBACK_PATH = "/api/partner/callbacks/**";

    @Value("${partner.callback.shared-secret}")
    private String partnerSharedSecret;

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        PartnerSignatureFilter signatureFilter =
                new PartnerSignatureFilter(partnerSharedSecret, List.of(PARTNER_CALLBACK_PATH));

        http
                .csrf(csrf -> csrf.ignoringRequestMatchers(new AntPathRequestMatcher(PARTNER_CALLBACK_PATH)))
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(new AntPathRequestMatcher(PARTNER_CALLBACK_PATH)).hasRole("PARTNER")
                        .anyRequest().authenticated()
                )
                .addFilterBefore(signatureFilter, UsernamePasswordAuthenticationFilter.class)
                .httpBasic(httpBasic -> httpBasic.disable())
                .formLogin(formLogin -> formLogin.disable());

        return http.build();
    }
}
