package com.example.partner.order;

import jakarta.validation.Valid;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt für Partner-Callbacks.
 *
 * - @Valid stößt die Bean-Validation-Constraints aus OrderCallbackRequest an
 *   (Allow-list-Validierung, siehe dort).
 * - consumes/produces sind strikt auf JSON beschränkt, sodass keine anderen
 *   Content-Types (z. B. multipart/form-data) missbraucht werden können.
 * - Die Authentifizierung erfolgt bereits vorgelagert im
 *   PartnerSignatureFilter; dieser Controller vertraut nur authentifizierten,
 *   validierten Requests.
 */
@RestController
@RequestMapping("/api/partner/callbacks")
public class OrderCallbackController {

    private final OrderService orderService;

    public OrderCallbackController(OrderService orderService) {
        this.orderService = orderService;
    }

    @PostMapping(
            value = "/orders",
            consumes = MediaType.APPLICATION_JSON_VALUE,
            produces = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<Void> handleOrderCallback(@Valid @RequestBody OrderCallbackRequest request) {
        orderService.upsertOrder(request);
        return ResponseEntity.ok().build();
    }
}
