"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.partner.error;

import com.example.partner.security.InvalidSignatureException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;

/**
 * Zentrale Fehlerbehandlung.
 *
 * - Gibt dem Client ausschließlich generische, unschädliche Meldungen zurück
 *   (kein Stacktrace, keine SQL-Fehlermeldungen -> Schutz vor CWE-209).
 * - Vor dem Loggen werden potenziell von Angreifern beeinflusste Strings
 *   von Zeilenumbrüchen bereinigt, um Log-Injection (CWE-117) zu verhindern.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ApiErrorResponse> handleValidation(MethodArgumentNotValidException ex,
                                                              WebRequest request) {
        log.warn("Validation failed for partner callback request: {}", sanitizeForLog(ex.getMessage()));
        ApiErrorResponse body = new ApiErrorResponse(
                HttpStatus.BAD_REQUEST.value(),
                "Bad Request",
                "The submitted callback payload is invalid.",
                extractPath(request));
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(body);
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<ApiErrorResponse> handleUnreadable(HttpMessageNotReadableException ex,
                                                              WebRequest request) {
        log.warn("Malformed JSON payload received: {}", sanitizeForLog(ex.getMessage()));
        ApiErrorResponse body = new ApiErrorResponse(
                HttpStatus.BAD_REQUEST.value(),
                "Bad Request",
                "The submitted payload could not be parsed.",
                extractPath(request));
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(body);
    }

    @ExceptionHandler(InvalidSignatureException.class)
    public ResponseEntity<ApiErrorResponse> handleInvalidSignature(InvalidSignatureException ex,
                                                                    WebRequest request) {
        log.warn("Invalid partner signature: {}", sanitizeForLog(ex.getMessage()));
        ApiErrorResponse body = new ApiErrorResponse(
                HttpStatus.UNAUTHORIZED.value(),
                "Unauthorized",
                "Partner authentication failed.",
                extractPath(request));
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(body);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ApiErrorResponse> handleGeneric(Exception ex, WebRequest request) {
        log.error("Unexpected error while processing partner callback", ex);
        ApiErrorResponse body = new ApiErrorResponse(
                HttpStatus.INTERNAL_SERVER_ERROR.value(),
                "Internal Server Error",
                "An unexpected error occurred while processing the request.",
                extractPath(request));
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }

    private String extractPath(WebRequest request) {
        return request.getDescription(false).replace("uri=", "");
    }

    private String sanitizeForLog(String input) {
        if (input == null) {
            return "";
        }
        return input.replaceAll("[\r\n]", "_");
    }
}
