/**
 * Eingabe-DTO für den Teil-Update ("PATCH") der Anwendungseinstellungen.
 * Alle Felder sind optional: null bedeutet "unverändert lassen".
 * Wenn ein Feld gesetzt ist, muss es die definierten Constraints erfüllen.
 */
public class SettingsUpdateRequest implements Serializable {

    private Role defaultRole;

    @DecimalMin(value = "0.00", message = "maxRefundAmount must not be negative")
    @DecimalMax(value = "1000000.00", message = "maxRefundAmount exceeds the allowed maximum")
    @Digits(integer = 7, fraction = 2, message = "maxRefundAmount has an invalid numeric format")
    private BigDecimal maxRefundAmount;

    @Size(max = 50, message = "A maximum of 50 feature flags is allowed")
    private Map<@Size(max = 100) String, Boolean> featureFlags;

    @Email(message = "supportEmail must be a valid email address")
    @Size(max = 254, message = "supportEmail is too long")
    private String supportEmail;

    private Boolean maintenanceMode;

    public SettingsUpdateRequest() {
    }

    public Role getDefaultRole() {
        return defaultRole;
    }

    public void setDefaultRole(Role defaultRole) {
        this.defaultRole = defaultRole;
    }

    public BigDecimal getMaxRefundAmount() {
        return maxRefundAmount;
    }

    public void setMaxRefundAmount(BigDecimal maxRefundAmount) {
        this.maxRefundAmount = maxRefundAmount;
