package com.example.settings;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

/**
 * Persistente, singleton-artige Konfigurationstabelle (immer genau eine Zeile).
 * Das Feld {@code version} sorgt für optimistisches Locking und verhindert
 * verlorene Updates bei parallelen Schreibzugriffen (Schutz vor CWE-362).
 */
@Entity
@Table(name = "application_settings")
public class ApplicationSettings {

    public static final long SINGLETON_ID = 1L;

    @Id
    private Long id = SINGLETON_ID;

    @Enumerated(EnumType.STRING)
    @Column(name = "default_role", nullable = false, length = 20)
    private Role defaultRole = Role.USER;

    @Column(name = "max_refund_amount", nullable = false, precision = 19, scale = 2)
    private BigDecimal maxRefundAmount = new BigDecimal("100.00");

    @ElementCollection
    @CollectionTable(name = "application_settings_feature_flags",
            joinColumns = @JoinColumn(name = "settings_id"))
    @MapKeyColumn(name = "flag_name", length = 100)
    @Column(name = "flag_value", nullable = false)
    private Map<String, Boolean> featureFlags = new HashMap<>();

    @Column(name = "support_email", nullable = false, length = 254)
    private String supportEmail = "support@example.com";

    @Column(name = "maintenance_mode", nullable = false)
    private boolean maintenanceMode = false;

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected ApplicationSettings() {
        // Von JPA benötigt
    }

    public static ApplicationSettings createDefault() {
        return new ApplicationSettings();
    }

    public Long getId() {
        return id;
    }

    public Role getDefaultRole() {
        return defaultRole;
    }

    public void setDefaultRole(Role defaultRole) {
        this.defaultRole = defaultRole;
    }

    public BigDecimal getMaxRefundAmount() {
        return maxRefundAmount;
    }

    public void setMaxRefundAmount(BigDecimal maxRefundAmount) {
        this.maxRefundAmount = maxRefundAmount;
    }

    public Map<String, Boolean> getFeatureFlags() {
        return featureFlags;
    }

    public void setFeatureFlags(Map<String, Boolean> featureFlags) {
        this.featureFlags = new HashMap<>(featureFlags);
    }

    public String getSupportEmail() {
        return supportEmail;
    }

    public void setSupportEmail(String supportEmail) {
        this.supportEmail = supportEmail;
    }

    public boolean isMaintenanceMode() {
        return maintenanceMode;
    }

    public void setMaintenanceMode(boolean maintenanceMode) {
        this.maintenanceMode = maintenanceMode;
    }

    public long getVersion() {
        return version;
    }
}
