"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ApplicationSettingsServiceImpl.java
package com.example.settings;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.HashMap;
import java.util.Map;

@Service
public class ApplicationSettingsServiceImpl implements ApplicationSettingsService {

    // Separater Audit-Logger, damit sicherheitsrelevante Ereignisse
    // gezielt ausgewertet/überwacht werden können.
    private static final Logger AUDIT_LOG = LoggerFactory.getLogger("AUDIT");

    private final ApplicationSettingsRepository repository;

    public ApplicationSettingsServiceImpl(ApplicationSettingsRepository repository) {
        this.repository = repository;
    }

    @Override
    @Transactional
    public SettingsResponse updateSettings(SettingsUpdateRequest request, String actor) {
        // Die einzelne Einstellungs-Zeile wird beim ersten legitimen,
        // authentifizierten Aufruf erzeugt und danach aktualisiert.
        // Die Methode läuft in einer Transaktion und nutzt optimistisches
        // Locking (@Version), sodass gleichzeitige Updates nicht
        // stillschweigend verloren gehen (Schutz vor CWE-362).
        ApplicationSettings settings = repository.findById(ApplicationSettings.SINGLETON_ID)
                .orElseGet(ApplicationSettings::createDefault);

        applyPartialUpdate(settings, request);

        try {
            ApplicationSettings saved = repository.save(settings);
            AUDIT_LOG.info("Application settings updated by administrator '{}'.", sanitizeForLog(actor));
            return toResponse(saved);
        } catch (ObjectOptimisticLockingFailureException e) {
            AUDIT_LOG.warn("Concurrent settings update conflict triggered by administrator '{}'.",
                    sanitizeForLog(actor));
            throw e;
        }
    }

    @Override
    @Transactional(readOnly = true)
    public SettingsResponse getSettings() {
        ApplicationSettings settings = repository.findById(ApplicationSettings.SINGLETON_ID)
                .orElseGet(ApplicationSettings::createDefault);
        return toResponse(settings);
    }

    private void applyPartialUpdate(ApplicationSettings settings, SettingsUpdateRequest request) {
        if (request.getDefaultRole() != null) {
            settings.setDefaultRole(request.getDefaultRole());
        }
        if (request.getMaxRefundAmount() != null) {
            settings.setMaxRefundAmount(request.getMaxRefundAmount());
        }
        if (request.getFeatureFlags() != null) {
            settings.setFeatureFlags(new HashMap<>(request.getFeatureFlags()));
        }
        if (request.getSupportEmail() != null) {
            settings.setSupportEmail(request.getSupportEmail());
        }
        if (request.getMaintenanceMode() != null) {
            settings.setMaintenanceMode(request.getMaintenanceMode());
        }
    }

    private SettingsResponse toResponse(ApplicationSettings settings) {
        return new SettingsResponse(
                settings.getDefaultRole(),
                settings.getMaxRefundAmount(),
                settings.getFeatureFlags(),
                settings.getSupportEmail(),
                settings.isMaintenanceMode()
        );
    }

    private String sanitizeForLog(String value) {
        if (value == null) {
            return "unknown";
        }
        // Entfernt CR/LF, um Log-Injection / Log-Forging zu verhindern (CWE-117).
        return value.replaceAll("[\\r\\n]", "_");
    }
}
