"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SettingsController.java
package com.example.settings;

import jakarta.validation.Valid;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Verwaltungsendpunkt für Anwendungseinstellungen.
 *
 * Zugriffskontrolle wird serverseitig für JEDEN Aufruf geprüft
 * (nicht nur beim "ersten" Aufruf), wie im REST Security Cheat Sheet
 * gefordert. Das schließt die Rechteausweitungslücke, die bei einem
 * unauthentifizierten "First-Call-Wins"-Setup entstehen würde
 * (CWE-862 / CWE-284).
 */
@RestController
@RequestMapping(value = "/api/admin/settings", produces = MediaType.APPLICATION_JSON_VALUE)
public class SettingsController {

    private final ApplicationSettingsService settingsService;

    public SettingsController(ApplicationSettingsService settingsService) {
        this.settingsService = settingsService;
    }

    @PreAuthorize("hasRole('ADMIN')")
    @PatchMapping(consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<SettingsResponse> updateSettings(
            @Valid @RequestBody SettingsUpdateRequest request,
            Authentication authentication) {

        String actor = authentication != null ? authentication.getName() : "unknown";
        SettingsResponse response = settingsService.updateSettings(request, actor);
        return ResponseEntity.ok()
                .header("Cache-Control", "no-store")
                .header("X-Content-Type-Options", "nosniff")
                .body(response);
    }

    @PreAuthorize("hasRole('ADMIN')")
    @GetMapping
    public ResponseEntity<SettingsResponse> getSettings() {
        return ResponseEntity.ok()
                .header("Cache-Control", "no-store")
                .header("X-Content-Type-Options", "nosniff")
                .body(settingsService.getSettings());
    }
}
