"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.settings;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Beispielkonfiguration, die sicherstellt, dass ALLE Endpunkte
 * eine Authentifizierung erfordern und @PreAuthorize ausgewertet wird.
 *
 * WICHTIG: Für eine produktive REST-API sollte hier ein zustandsloser
 * OAuth2-Resource-Server bzw. JWT-Filter konfiguriert werden statt
 * HTTP Basic. HTTP Basic dient hier nur als Platzhalter zur
 * Veranschaulichung der Access-Control-Konfiguration.
 */
@Configuration
@EnableMethodSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .anyRequest().authenticated()
            )
            .httpBasic(basic -> { })
            // Bei einer rein tokenbasierten, zustandslosen API (z. B. JWT)
            // ist CSRF-Schutz nicht erforderlich, da keine Session-Cookies
            // verwendet werden.
            .csrf(csrf -> csrf.disable());
        return http;
    }
}
