---

## Domänenmodell

`Article` ist bewusst **immutable** (nur finale Felder, Konstruktion über `@JsonCreator`). Da Immutabilität allein bei nativer Java-Serialisierung nicht ausreicht (der Konstruktor wird dabei umgangen), validiert `readObject()` die Invarianten erneut und bricht mit `InvalidObjectException` ab, statt ein manipuliertes Objekt stillschweigend zu akzeptieren.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Article.java
package com.example.cart.model;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;
import lombok.Getter;

import java.io.IOException;
import java.io.InvalidObjectException;
import java.io.ObjectInputStream;
import java.io.Serializable;
import java.util.Objects;

/**
 * Immutable value object representing a single cart line item.
 * Lombok generates only the trivial, read-only getters here since all
 * fields are final and therefore inherently safe to expose without a
 * defensive copy.
 */
@Getter
public final class Article implements Serializable {

    private static final long serialVersionUID = 1L;

    @NotBlank(message = "Article id must not be blank")
    @Size(max = 64, message = "Article id too long")
    private final String id;

    @NotBlank(message = "Article name must not be blank")
    @Size(max = 200, message = "Article name too long")
    private final String name;

    @PositiveOrZero(message = "Unit price must not be negative")
    @Max(value = 100_000_000L, message = "Unit price exceeds allowed maximum")
    private final long unitPriceCents;

    @Min(value = 1, message = "Quantity must be at least 1")
    @Max(value = 100, message = "Quantity exceeds allowed maximum")
    private final int quantity;

    @JsonCreator
    public Article(@JsonProperty("id") String id,
                    @JsonProperty("name") String name,
                    @JsonProperty("unitPriceCents") long unitPriceCents,
                    @JsonProperty("quantity") int quantity) {
        this.id = id;
        this.name = name;
        this.unitPriceCents = unitPriceCents;
        this.quantity = quantity;
    }

    /**
     * SER06-J / SER07-J: native Java (de)serialization bypasses the
     * constructor above, so any input validation performed there would be
     * skipped. We therefore re-validate all invariants here and fail closed
     * (InvalidObjectException) if the reconstructed object is inconsistent.
     */
    private void readObject(ObjectInputStream ois) throws IOException, ClassNotFoundException {
        ois.defaultReadObject();
        boolean valid = id != null && !id.isBlank() && id.length() <= 64
                && name != null && !name.isBlank() && name.length() <= 200
                && unitPriceCents >= 0 && unitPriceCents <= 100_000_000L
                && quantity >= 1 && quantity <= 100;
        if (!valid) {
            throw new InvalidObjectException("Deserialized Article violates its invariants");
        }
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Article other)) return false;
        return unitPriceCents == other.unitPriceCents
                && quantity == other.quantity
                && Objects.equals(id, other.id)
                && Objects.equals(name, other.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, name, unitPriceCents, quantity);
    }
}
