`Cart` enthält die einzige "wirklich" mutable Komponente – die Liste der Artikel. Das Feld ist bewusst **nicht `final`**, damit `readObject()` es (wie von CERT SER06-J gefordert) mit einer frischen, defensiven, unveränderlichen Kopie überschreiben kann; ein `final`-Feld ließe sich außerhalb des Konstruktors gar nicht neu zuweisen.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Cart.java
package com.example.cart.model;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.io.IOException;
import java.io.InvalidObjectException;
import java.io.ObjectInputStream;
import java.io.Serializable;
import java.util.List;

/**
 * Cart aggregate. Note that identity-/payment-related fields (e.g. a user
 * id) are intentionally NOT part of this class. Such data must never be
 * trusted from client-controlled deserialized input; it has to be derived
 * server-side from the authenticated security context instead.
 */
public final class Cart implements Serializable {

    private static final long serialVersionUID = 1L;
    private static final int MAX_ARTICLES = 100;

    /**
     * Deliberately NOT final (SER06-J): readObject() must be able to
     * reassign this field with a freshly, defensively copied, immutable
     * list after the raw stream data has been restored.
     */
    @NotEmpty(message = "Cart must contain at least one article")
    @Size(max = MAX_ARTICLES, message = "Too many articles in cart")
    private List<@Valid Article> articles;

    @JsonCreator
    public Cart(@JsonProperty("articles") List<Article> articles) {
        this.articles = defensiveImmutableCopy(articles);
        validateInvariants();
    }

    /** The stored list is already an immutable snapshot, so returning it directly is safe. */
    public List<Article> getArticles() {
        return articles;
    }

    private static List<Article> defensiveImmutableCopy(List<Article> input) {
        // List.copyOf() rejects null elements and never exposes the
        // caller's backing collection, closing off post-construction
        // mutation paths entirely.
        return input == null ? List.of() : List.copyOf(input);
    }

    private void validateInvariants() {
        if (articles.isEmpty() || articles.size() > MAX_ARTICLES) {
            throw new IllegalStateException("Cart violates article count invariants");
        }
    }

    /**
     * SER06-J / SER07-J: deserialization is equivalent to object
     * construction and must enforce the same invariants. We re-apply the
     * defensive copy and re-validate; any violation causes a fail-closed
     * InvalidObjectException instead of accepting a tampered object graph.
     */
    private void readObject(ObjectInputStream ois) throws IOException, ClassNotFoundException {
        ois.defaultReadObject();
        try {
            this.articles = defensiveImmutableCopy(articles);
            validateInvariants();
        } catch (RuntimeException e) {
            throw new InvalidObjectException("Deserialized Cart violates its invariants: " + e.getMessage());
        }
    }
}
