## Gehärtete Jackson-Konfiguration

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// JacksonConfig.java
package com.example.cart.config;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.StreamReadConstraints;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.json.JsonMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;

@Configuration
public class JacksonConfig {

    /**
     * Hardened ObjectMapper dedicated to parsing the untrusted,
     * Base64-decoded cart payload (CWE-502 mitigation):
     *  - Polymorphic / "default typing" deserialization is never enabled,
     *    so an attacker cannot smuggle arbitrary class names into the JSON
     *    to trigger gadget-chain instantiation.
     *  - Unknown properties are rejected outright, so fields such as
     *    "userId" or "paymentToken", which are not part of the public
     *    Cart contract, are never silently accepted from client input.
     *  - Stream constraints cap string length and nesting depth to
     *    prevent algorithmic-complexity / stack-overflow denial-of-service
     *    attacks (CWE-400) via deeply nested or oversized JSON.
     *
     * Requires jackson-core >= 2.15 for StreamReadConstraints.
     */
    @Bean
    @Primary
    public ObjectMapper cartObjectMapper() {
        StreamReadConstraints constraints = StreamReadConstraints.builder()
                .maxNestingDepth(20)
                .maxStringLength(50_000)
                .build();

        JsonFactory jsonFactory = JsonFactory.builder()
                .streamReadConstraints(constraints)
                .build();

        ObjectMapper mapper = JsonMapper.builder(jsonFactory).build();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, true);
        // Explicit, defense-in-depth: default typing must never be active.
        mapper.deactivateDefaultTyping();
        return mapper;
    }
}
