package com.example.cart.service;

import com.example.cart.dto.ArticleResponse;
import com.example.cart.dto.CartResponse;
import com.example.cart.exception.InvalidCartDataException;
import com.example.cart.model.Article;
import com.example.cart.model.Cart;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.ConstraintViolation;
import jakarta.validation.Validator;
import org.springframework.stereotype.Service;

import java.util.Base64;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

@Service
public class CartService {

    // Upper bound for the decoded payload size, independent of the
    // Base64 string length check on the DTO (defense in depth, CWE-400).
    private static final int MAX_DECODED_BYTES = 200_000;

    private final ObjectMapper cartObjectMapper;
    private final Validator validator;

    public CartService(ObjectMapper cartObjectMapper, Validator validator) {
        this.cartObjectMapper = cartObjectMapper;
        this.validator = validator;
    }

    public CartResponse decodeAndReconstruct(String base64CartData) {
        byte[] decoded = decodeBase64(base64CartData);
        Cart cart = parseCart(decoded);
        validateWithBeanValidation(cart);
        return buildResponse(cart);
    }

    private byte[] decodeBase64(String base64CartData) {
        byte[] decoded;
        try {
            // Strict decoder: rejects illegal characters instead of
            // silently ignoring them (fail closed, CWE-20 mitigation).
            decoded = Base64.getDecoder().decode(base64CartData.trim());
        } catch (IllegalArgumentException e) {
            throw new InvalidCartDataException("cartData is not valid Base64 content");
        }
        if (decoded.length == 0 || decoded.length > MAX_DECODED_BYTES) {
            throw new InvalidCartDataException("Decoded cart payload size is not allowed");
        }
        return decoded;
    }

    private Cart parseCart(byte[] decoded) {
        try {
            // Any unexpected/extra property (e.g. "userId", "paymentToken")
            // causes FAIL_ON_UNKNOWN_PROPERTIES to reject the payload here.
            return cartObjectMapper.readValue(decoded, Cart.class);
        } catch (JsonProcessingException e) {
            throw new InvalidCartDataException("cartData does not contain a valid cart structure");
        }
    }

    private void validateWithBeanValidation(Cart cart) {
        // @Valid on the List<Article> field cascades into every article.
        Set<ConstraintViolation<Cart>> violations = validator.validate(cart);
        if (!violations.isEmpty()) {
            throw new InvalidCartDataException("Cart data failed validation");
        }
    }

    private CartResponse buildResponse(Cart cart) {
        List<ArticleResponse> responseArticles = cart.getArticles().stream()
                .map(a -> new ArticleResponse(a.getId(), a.getName(), a.getUnitPriceCents(), a.getQuantity()))
                .collect(Collectors.toList());

        long totalSum = 0L;
        for (Article article : cart.getArticles()) {
            // Overflow-safe arithmetic (CWE-190) — the total is computed
            // exclusively server-side from validated data, never trusted
            // from the client (prevents price/total tampering, CWE-807).
            long lineTotal = Math.multiplyExact(article.getUnitPriceCents(), (long) article.getQuantity());
            totalSum = Math.addExact(totalSum, lineTotal);
        }

        return new CartResponse(responseArticles, totalSum);
    }
}
