package com.example.cart.web;

import com.example.cart.dto.CartRequest;
import com.example.cart.dto.CartResponse;
import com.example.cart.service.CartService;
import jakarta.validation.Valid;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/cart")
public class CartController {

    private final CartService cartService;

    public CartController(CartService cartService) {
        this.cartService = cartService;
    }

    @PostMapping(value = "/decode", produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<CartResponse> decodeCart(@Valid @RequestBody CartRequest request) {
        CartResponse response = cartService.decodeAndReconstruct(request.getCartData());
        return ResponseEntity.ok(response);
    }
}
