package com.example.customersecure.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Zentrale Sicherheitskonfiguration:
 * - HTTP Basic Authentication
 * - zustandslose Sessions (kein Session-Fixation-Risiko, CSRF nicht relevant)
 * - Deny-by-default für alle nicht explizit erlaubten Pfade
 * - BCrypt-gehashte Zugangsdaten aus der Konfiguration (nie hartkodiert)
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Value("${app.security.api-username}")
    private String apiUsername;

    @Value("${app.security.api-password-hash}")
    private String apiPasswordHash;

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12);
    }

    @Bean
    public InMemoryUserDetailsManager userDetailsService() {
        UserDetails apiUser = User.withUsername(apiUsername)
                .password(apiPasswordHash) // bereits als BCrypt-Hash konfiguriert
                .roles("API_USER")
                .build();
        return new InMemoryUserDetailsManager(apiUser);
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            // Sicher, da zustandslose Basic-Auth-API ohne Session-Cookies verwendet wird
            .csrf(csrf -> csrf.disable())
            .sessionManagement(sm -> sm.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/customers/**").hasRole("API_USER")
                .anyRequest().denyAll()
            )
            .httpBasic(basic -> {});
        return http.build();
    }
}
