package com.example.customersecure.util;

import com.example.customersecure.exception.InvalidInputException;

import java.text.Normalizer;
import java.util.regex.Pattern;

/**
 * Whitelist-basierte Eingabevalidierung für den customerName-Parameter.
 * Erlaubt nur Buchstaben (inkl. Unicode), Leerzeichen, Punkt, Bindestrich
 * und Apostroph. Blockiert damit u. a. Anführungszeichen, spitze Klammern,
 * Semikolons und andere für Injection-Angriffe typische Zeichen.
 *
 * Dies ist eine zusätzliche Verteidigungslinie (Defense in Depth) zur
 * parametrisierten XPath-Abfrage im Repository.
 */
public final class InputSanitizer {

    private static final Pattern ALLOWED_CUSTOMER_NAME =
            Pattern.compile("^[\\p{L}\\p{M} .'-]{1,100}$");

    private InputSanitizer() {
    }

    public static String sanitizeCustomerName(String rawInput) {
        if (rawInput == null || rawInput.isBlank()) {
            throw new InvalidInputException("customerName darf nicht leer sein.");
        }

        String normalized = Normalizer.normalize(rawInput.trim(), Normalizer.Form.NFKC);

        if (!ALLOWED_CUSTOMER_NAME.matcher(normalized).matches()) {
            throw new InvalidInputException("customerName enthält unzulässige Zeichen.");
        }

        return normalized;
    }
}
