/**
 * Defense-in-Depth: Selbst falls DOCTYPE-Verarbeitung jemals versehentlich
 * wieder aktiviert würde, löst dieser Resolver niemals eine externe
 * Entity auf, sondern liefert stets einen leeren Inhalt zurück.
 */
public final class NoOpEntityResolver implements EntityResolver {

    @Override
    public InputSource resolveEntity(String publicId, String systemId) {
        return new InputSource(new StringReader(""));
    }
}
