package com.example.customersecure.xml;

import org.xml.sax.ErrorHandler;
import org.xml.sax.SAXException;
import org.xml.sax.SAXParseException;

/**
 * Bricht das Parsen bei jeder Warnung, jedem Fehler und jedem fatalen
 * Fehler der XSD-Validierung sofort ab ("fail fast"), statt ein
 * möglicherweise fehlerhaftes oder manipuliertes Dokument stillschweigend
 * weiterzuverarbeiten.
 */
public final class StrictValidationErrorHandler implements ErrorHandler {

    @Override
    public void warning(SAXParseException exception) throws SAXException {
        throw exception;
    }

    @Override
    public void error(SAXParseException exception) throws SAXException {
        throw exception;
    }

    @Override
    public void fatalError(SAXParseException exception) throws SAXException {
        throw exception;
    }
}
