package com.example.customersecure.repository;

import com.example.customersecure.dto.Customer;
import com.example.customersecure.exception.XmlProcessingException;
import com.example.customersecure.xml.NoOpEntityResolver;
import com.example.customersecure.xml.StrictValidationErrorHandler;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.springframework.core.io.ResourceLoader;
import org.springframework.stereotype.Repository;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.xml.sax.SAXException;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathExpressionException;
import javax.xml.xpath.XPathFactory;
import javax.xml.xpath.XPathFactoryConfigurationException;
import java.io.IOException;
import java.io.InputStream;
import java.util.Optional;

/**
 * Gehärtete XML-Datenquelle:
 *  - DOCTYPE-Deklarationen sind vollständig verboten (primäre XXE-Abwehr,
 *    verhindert zugleich "Billion Laughs"-DoS-Angriffe).
 *  - Externe Entities/DTDs sind zusätzlich explizit deaktiviert.
 *  - Das Dokument wird strikt gegen eine vordefinierte XSD validiert.
 *  - Die Suche erfolgt über eine parametrisierte XPath-Abfrage (Bind-
 *    Variable statt String-Konkatenation) und verhindert damit
 *    XPath-Injection (das XML-Äquivalent zu CWE-89 SQL-Injection).
 */
@Repository
public class CustomerXmlRepositoryImpl implements CustomerXmlRepository {

    private final Resource customersXmlResource;
    private final Resource customersXsdResource;

    public CustomerXmlRepositoryImpl(
            ResourceLoader resourceLoader,
            @Value("${app.xml.customers-file}") String customersFileLocation,
            @Value("${app.xml.schema-file}") String schemaFileLocation) {
        this.customersXmlResource = resourceLoader.getResource(customersFileLocation);
        this.customersXsdResource = resourceLoader.getResource(schemaFileLocation);
    }

    @Override
    public Optional<Customer> findByName(String sanitizedCustomerName) {
        Document document = parseAndValidate();
        return searchCustomerByName(document, sanitizedCustomerName);
    }

    private Document parseAndValidate() {
        try (InputStream xmlStream = customersXmlResource.getInputStream()) {

            Schema schema = loadSchema();

            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

            // Primäre XXE-/DoS-Abwehr: DOCTYPE komplett verbieten
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Defense in Depth
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            factory.setXIncludeAware(false);
            factory.setExpandEntityReferences(false);
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            factory.setNamespaceAware(true);

            // Strikte XSD-Validierung statt DTD-Validierung
            factory.setValidating(false);
            factory.setSchema(schema);

            DocumentBuilder builder = factory.newDocumentBuilder();
            builder.setEntityResolver(new NoOpEntityResolver());
            builder.setErrorHandler(new StrictValidationErrorHandler());

            return builder.parse(xmlStream);

        } catch (ParserConfigurationException | SAXException | IOException e) {
            throw new XmlProcessingException(
                    "Die Kunden-XML-Quelle konnte nicht sicher geparst oder validiert werden.", e);
        }
    }

    private Schema loadSchema() {
        try (InputStream xsdStream = customersXsdResource.getInputStream()) {
            SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);

            // Verhindert, dass die SchemaFactory selbst externe DTDs/Schemas nachlädt
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            return schemaFactory.newSchema(new StreamSource(xsdStream));
        } catch (IOException | SAXException e) {
            throw new XmlProcessingException("Das XML-Schema (XSD) konnte nicht geladen werden.", e);
        }
    }

    private Optional<Customer> searchCustomerByName(Document document, String sanitizedCustomerName) {
        try {
            XPathFactory xPathFactory = XPathFactory.newInstance();
            xPathFactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            XPath xpath = xPathFactory.newXPath();

            // Der Kundenname wird als GEBUNDENE VARIABLE übergeben, niemals in den
            // XPath-Ausdruck hineinkonkateniert. Dies ist das XML-Äquivalent eines
            // SQL-Prepared-Statements und verhindert XPath-Injection strukturell.
            xpath.setXPathVariableResolver(variableName -> {
                if ("customerName".equals(variableName.getLocalPart())) {
                    return sanitizedCustomerName;
                }
                return null;
            });

            XPathExpression expression =
                    xpath.compile("//customer[normalize-space(name) = $customerName]");

            Element customerElement = (Element) expression.evaluate(document, XPathConstants.NODE);

            if (customerElement == null) {
                return Optional.empty();
            }

            String id = getChildText(customerElement, "id");
            String name = getChildText(customerElement, "name");
            String email = getChildText(customerElement, "email");

            return Optional.of(new Customer(id, name, email));

        } catch (XPathExpressionException | XPathFactoryConfigurationException e) {
            throw new XmlProcessingException("Die Kundensuche konnte nicht ausgeführt werden.", e);
        }
    }

    private String getChildText(Element parent, String tagName) {
        var nodeList = parent.getElementsByTagName(tagName);
        if (nodeList.getLength() == 0) {
            return null;
        }
        return nodeList.item(0).getTextContent();
    }
}
