package com.example.customersecure.controller;

import com.example.customersecure.dto.Customer;
import com.example.customersecure.service.CustomerService;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
public class CustomerController {

    private final CustomerService customerService;

    public CustomerController(CustomerService customerService) {
        this.customerService = customerService;
    }

    /**
     * Sucht einen Kunden anhand des Namens in der XML-Datenquelle.
     * Der Endpoint ist über Spring Security (HTTP Basic) abgesichert
     * (siehe SecurityConfig) und erfordert die Rolle API_USER.
     */
    @GetMapping("/api/customers")
    public ResponseEntity<Customer> getCustomerByName(
            @RequestParam("customerName")
            @NotBlank
            @Size(max = 100)
            String customerName) {

        Customer customer = customerService.findByCustomerName(customerName);
        return ResponseEntity.ok(customer);
    }
}
