"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.customersecure.exception;

import com.example.customersecure.dto.ErrorResponse;
import jakarta.validation.ConstraintViolationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.Instant;

/**
 * Zentrale Fehlerbehandlung. Gibt gegenüber dem Client bewusst nur
 * generische Meldungen aus, um keine internen Implementierungsdetails,
 * Stacktraces oder Systempfade preiszugeben (Schutz vor CWE-209).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(CustomerNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleNotFound(CustomerNotFoundException ex) {
        return buildResponse(HttpStatus.NOT_FOUND, "Kunde nicht gefunden.");
    }

    @ExceptionHandler({InvalidInputException.class, ConstraintViolationException.class})
    public ResponseEntity<ErrorResponse> handleBadRequest(RuntimeException ex) {
        return buildResponse(HttpStatus.BAD_REQUEST, "Ungültige Anfrageparameter.");
    }

    @ExceptionHandler(XmlProcessingException.class)
    public ResponseEntity<ErrorResponse> handleXmlProcessing(XmlProcessingException ex) {
        log.error("Fehler bei der XML-Verarbeitung", ex);
        return buildResponse(HttpStatus.INTERNAL_SERVER_ERROR, "Die Anfrage konnte nicht verarbeitet werden.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGeneric(Exception ex) {
        log.error("Unbehandelte Ausnahme", ex);
        return buildResponse(HttpStatus.INTERNAL_SERVER_ERROR, "Es ist ein unerwarteter Fehler aufgetreten.");
    }

    private ResponseEntity<ErrorResponse> buildResponse(HttpStatus status, String message) {
        ErrorResponse body = new ErrorResponse(Instant.now(), status.value(), status.getReasonPhrase(), message);
        return ResponseEntity.status(status).body(body);
    }
}
