---

### 2. Exceptions

`UrlValidationException` signalisiert, dass die Eingabe des Clients die SSRF-Prüfung nicht bestanden hat. `UrlFetchException` kapselt Fehler beim eigentlichen Netzwerkzugriff. Beide tragen bewusst nur sichere, generische Nachrichten – die eigentliche technische Ursache (Stacktrace, interne Hostnamen etc.) wird ausschließlich serverseitig geloggt, niemals über die Exception-Message an den Client weitergereicht (CERT ERR01-J, CWE-209).

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlValidationException.java
package com.example.urlfetch.exception;

/**
 * Wird geworfen, wenn die vom Client übergebene URL die SSRF-Validierung
 * nicht besteht. Die Message darf ausschließlich generische, für den
 * Client unbedenkliche Hinweise enthalten.
 */
public class UrlValidationException extends RuntimeException {

    public UrlValidationException(String message) {
        super(message);
    }
}
", "fileName": "Component_2", "vulnerbility": null}, {"type": "TEXT", "text": "

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlFetchException.java
package com.example.urlfetch.exception;

/**
 * Wird geworfen, wenn der eigentliche HTTP-Abruf fehlschlägt
 * (z. B. Timeout, Verbindungsfehler). Die ursprüngliche Ursache wird
 * als "cause" mitgegeben, damit sie serverseitig geloggt werden kann,
 * ohne dass sie in einer HTTP-Antwort landet.
 */
public class UrlFetchException extends RuntimeException {

    public UrlFetchException(String message, Throwable cause) {
        super(message, cause);
    }
}
