### 3. SSRF-Validator

Dies ist die wichtigste Sicherheitskomponente. Sie nutzt `java.net.URI` (strikte RFC-3986-Parsierung) und prüft anschließend **jede aufgelöste IP-Adresse** des Hostnamens gegen bekannte private/reservierte Bereiche sowie den Cloud-Metadaten-Endpunkt.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SsrfUrlValidator.java
package com.example.urlfetch.validation;

import com.example.urlfetch.exception.UrlValidationException;
import org.springframework.stereotype.Component;

import java.net.Inet4Address;
import java.net.Inet6Address;
import java.net.InetAddress;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.UnknownHostException;
import java.util.Set;

/**
 * Validiert extern übergebene URLs, bevor sie für einen serverseitigen
 * HTTP-Request verwendet werden. Implementiert ein Allowlist-Modell zur
 * Abwehr von Server-Side Request Forgery (SSRF, CWE-918).
 */
@Component
public class SsrfUrlValidator {

    private static final Set<String> ALLOWED_SCHEMES = Set.of("https");
    private static final Set<Integer> ALLOWED_PORTS = Set.of(443, -1);

    public URI validate(String rawUrl) {
        if (rawUrl == null || rawUrl.isBlank() || rawUrl.length() > 2048) {
            throw new UrlValidationException("Invalid URL supplied.");
        }

        URI uri;
        try {
            uri = new URI(rawUrl.trim());
        } catch (URISyntaxException e) {
            throw new UrlValidationException("Malformed URL syntax.");
        }

        if (uri.getScheme() == null || !ALLOWED_SCHEMES.contains(uri.getScheme().toLowerCase())) {
            throw new UrlValidationException("URL scheme not permitted.");
        }

        if (uri.getUserInfo() != null) {
            // Eingebettete Zugangsdaten (user:pass@host) sind ein typischer
            // SSRF-/Credential-Leak-Vektor und werden daher abgelehnt.
            throw new UrlValidationException("Embedded credentials are not permitted.");
        }

        String host = uri.getHost();
        if (host == null || host.isBlank()) {
            throw new UrlValidationException("URL host is missing.");
        }

        if (!ALLOWED_PORTS.contains(uri.getPort())) {
            throw new UrlValidationException("URL port not permitted.");
        }

        if (isDisallowedHostname(host)) {
            throw new UrlValidationException("Target host is not permitted.");
        }

        resolveAndValidateAddresses(host);

        return uri;
    }

    private boolean isDisallowedHostname(String host) {
        String normalized = host.toLowerCase();
        return normalized.equals("localhost")
                || normalized.endsWith(".localhost")
                || normalized.equals("metadata.google.internal");
    }

    private void resolveAndValidateAddresses(String host) {
        InetAddress[] addresses;
        try {
            addresses = InetAddress.getAllByName(host);
        } catch (UnknownHostException e) {
            throw new UrlValidationException("Target host could not be resolved.");
        }

        if (addresses.length == 0) {
            throw new UrlValidationException("Target host could not be resolved.");
        }

        for (InetAddress address : addresses) {
            if (isBlockedAddress(address)) {
                // Ablehnung bereits bei der ersten unzulässigen Adresse
                // verhindert DNS-Rebinding-Angriffe, bei denen nur ein
                // Teil der DNS-Antworten auf interne Infrastruktur zeigt.
                throw new UrlValidationException("Target host resolves to a disallowed network range.");
            }
        }
    }

    private boolean isBlockedAddress(InetAddress address) {
        return address.isAnyLocalAddress()
                || address.isLoopbackAddress()
                || address.isLinkLocalAddress()
                || address.isSiteLocalAddress()
                || address.isMulticastAddress()
                || isCloudMetadataAddress(address)
                || (address instanceof Inet4Address && isReservedIpv4(address.getHostAddress()))
                || (address instanceof Inet6Address && isUniqueLocalIpv6(address.getHostAddress()));
    }

    private boolean isCloudMetadataAddress(InetAddress address) {
        // 169.254.169.254 ist der bekannte Cloud-Metadaten-Endpunkt
        // (AWS/GCP/Azure) und ein häufiges SSRF-Angriffsziel.
        return "169.254.169.254".equals(address.getHostAddress());
    }

    private boolean isReservedIpv4(String ip) {
        return ip.startsWith("0.") || ip.startsWith("100.64.") || ip.startsWith("198.18.");
    }

    private boolean isUniqueLocalIpv6(String ip) {
        String lower = ip.toLowerCase();
        return lower.startsWith("fc") || lower.startsWith("fd");
    }
}
