---

### 4. Fetch-Service

Der Service führt den eigentlichen Request mit strikten Timeouts, deaktivierten Redirects und einer Obergrenze für die Antwortgröße aus. Netzwerkfehler werden per `try-catch` abgefangen und in `UrlFetchException` umgewandelt – die Original-Exception wird nur geloggt, nicht an den Client weitergegeben.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlFetchService.java
package com.example.urlfetch.service;

import com.example.urlfetch.dto.UrlFetchResponse;
import com.example.urlfetch.exception.UrlFetchException;
import com.example.urlfetch.validation.SsrfUrlValidator;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

@Service
public class UrlFetchService {

    private static final Logger log = LoggerFactory.getLogger(UrlFetchService.class);

    // Harte Obergrenze zur Vermeidung unbegrenzten Speicherverbrauchs
    // durch übergroße Antworten (CWE-400).
    private static final long MAX_RESPONSE_BYTES = 1_048_576L; // 1 MiB
    private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(3);
    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(5);

    private final SsrfUrlValidator urlValidator;
    private final HttpClient httpClient;

    public UrlFetchService(SsrfUrlValidator urlValidator) {
        this.urlValidator = urlValidator;
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(CONNECT_TIMEOUT)
                // Automatische Redirects werden deaktiviert, damit ein
                // zunächst erlaubtes Ziel nicht serverseitig auf ein
                // internes Ziel umleiten kann (SSRF-Bypass, CWE-918).
                .followRedirects(HttpClient.Redirect.NEVER)
                .build();
    }

    public UrlFetchResponse fetch(String rawUrl) {
        // Die eigentliche SSRF-Härtung (Schema-, Allowlist-, DNS- und
        // IP-Range-Prüfung) erfolgt vollständig im SsrfUrlValidator.
        // Erst nach erfolgreicher Validierung wird die tatsächlich
        // verwendete, normalisierte URI für den Request genutzt.
        URI validatedUri = urlValidator.validate(rawUrl);

        HttpRequest request = HttpRequest.newBuilder(validatedUri)
                .GET()
                .timeout(REQUEST_TIMEOUT)
                .build();

        try {
            HttpResponse<String> response = httpClient.send(
                    request, HttpResponse.BodyHandlers.ofString());

            // Redirect-Antworten werden nicht automatisch weiterverfolgt
            // (siehe Redirect.NEVER oben) und daher hier nicht separat
            // ausgewertet - sie liefern lediglich den Redirect-Body,
            // ohne dass ein zweiter, ungeprüfter Request ausgelöst wird.

            String body = response.body();
            if (body != null) {
                byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
                if (bytes.length > MAX_RESPONSE_BYTES) {
                    body = new String(bytes, 0, (int) MAX_RESPONSE_BYTES, StandardCharsets.UTF_8);
                }
            }
            return new UrlFetchResponse(body);
        } catch (IOException | InterruptedException e) {
            // Technische Details werden ausschließlich serverseitig
            // geloggt, niemals an den Aufrufer zurückgegeben
            // (CERT ERR01-J / CWE-209). Es wird bewusst kein Hostname
            // oder e.getMessage() geloggt, um auch Log-Injection
            // (CWE-117) über die Nutzereingabe zu vermeiden.
            log.warn("Failed to fetch remote URL. Cause type: {}", e.getClass().getSimpleName());
            if (Thread.currentThread().isInterrupted()) {
                Thread.currentThread().interrupt();
            }
            throw new UrlFetchException("Unable to fetch the requested resource.", e);
        }
    }
}
