### 5. Controller

Der Controller erzwingt Autorisierung über `@PreAuthorize`, ruft den Service in einem `try-catch`-Block auf und mappt beide erwarteten Exception-Typen auf generische HTTP-Antworten. Der rohe Client-Input wird niemals in die Fehlermeldung übernommen.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlFetchController.java
package com.example.urlfetch.controller;

import com.example.urlfetch.dto.UrlFetchResponse;
import com.example.urlfetch.exception.UrlFetchException;
import com.example.urlfetch.exception.UrlValidationException;
import com.example.urlfetch.service.UrlFetchService;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class UrlFetchController {

    private final UrlFetchService urlFetchService;

    public UrlFetchController(UrlFetchService urlFetchService) {
        this.urlFetchService = urlFetchService;
    }

    /**
     * Ruft den textuellen Inhalt einer extern übergebenen URL ab.
     * Erfordert einen authentifizierten Aufrufer mit der Authority
     * ROLE_URL_FETCH (CWE-284) und wird zusätzlich durch den
     * RateLimitingFilter gegen Missbrauch abgesichert (CWE-400).
     */
    @PreAuthorize("hasAuthority('ROLE_URL_FETCH')")
    @GetMapping(value = "/api/v1/url-fetch", produces = MediaType.TEXT_PLAIN_VALUE)
    public ResponseEntity<String> fetchUrl(@RequestParam("url") String url) {
        try {
            UrlFetchResponse response = urlFetchService.fetch(url);
            return ResponseEntity.ok(response.body());
        } catch (UrlValidationException e) {
            // Es wird nur eine generische Meldung zurückgegeben; der
            // rohe Client-Input wird nicht reflektiert, um sowohl
            // Information Disclosure (CWE-209) als auch eine mögliche
            // Ausgabe von unbereinigtem Input (CWE-79) zu vermeiden.
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body("The supplied URL could not be validated.");
        } catch (UrlFetchException e) {
            return ResponseEntity.status(HttpStatus.BAD_GATEWAY)
                    .body("The requested resource could not be retrieved.");
        }
    }
}
