### 7. Rate-Limiting-Filter

Ein Token-Bucket-Filter (Bucket4j) begrenzt Anfragen pro Client-IP auf den geschützten Pfad, um Denial-of-Service-Missbrauch zu erschweren (CWE-400). In einer Cluster-Umgebung sollte der In-Memory-Speicher durch einen verteilten Store (z. B. Redis) ersetzt werden.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitingFilter.java
package com.example.urlfetch.security;

import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Refill;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.time.Duration;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

/**
 * Wendet ein einfaches Token-Bucket-Rate-Limit pro Client-IP auf den
 * URL-Fetch-Endpunkt an, um Denial-of-Service-Missbrauch zu reduzieren
 * (CWE-400).
 */
@Component
public class RateLimitingFilter extends OncePerRequestFilter {

    private static final String PROTECTED_PATH = "/api/v1/url-fetch";
    private static final int CAPACITY = 10;
    private static final Duration REFILL_PERIOD = Duration.ofMinutes(1);

    private final ConcurrentMap<String, Bucket> buckets = new ConcurrentHashMap<>();

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                     HttpServletResponse response,
                                     FilterChain filterChain) throws ServletException, IOException {

        if (!PROTECTED_PATH.equals(request.getRequestURI())) {
            filterChain.doFilter(request, response);
            return;
        }

        String clientKey = resolveClientKey(request);
        Bucket bucket = buckets.computeIfAbsent(clientKey, key -> newBucket());

        if (bucket.tryConsume(1)) {
            filterChain.doFilter(request, response);
        } else {
            response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
            response.setContentType("text/plain");
            response.getWriter().write("Too many requests. Please try again later.");
        }
    }

    private Bucket newBucket() {
        Bandwidth limit = Bandwidth.classic(CAPACITY, Refill.greedy(CAPACITY, REFILL_PERIOD));
        return Bucket.builder().addLimit(limit).build();
    }

    private String resolveClientKey(HttpServletRequest request) {
        // Es wird bewusst die vom Servlet-Container ermittelte
        // Remote-Adresse verwendet und nicht client-kontrollierbare
        // Header wie X-Forwarded-For, um eine triviale Umgehung des
        // Rate-Limits per Header-Spoofing zu verhindern.
        return request.getRemoteAddr();
    }
}
", "fileName": "Component_8", "vulnerbility": null}, {"type": "TEXT", "text": "

